NIGHT_LOADED({"seed":1119,"generated_at":"2026-10-21T06:00:00Z","chain":[1,2,3,4,5],"frame":{"collector":"J.J.V.","intro":["Je bent de nieuwe assistent.","Op tafel ligt een briefje van de verzamelaar.","De sleutel van de voordeur zit in zijn jas, en hij is naar huis.","De klok zegt kwart over negen.","Je begint te ordenen."],"note_table":"Twaalf enveloppen invoegen.\nKast vijf blijft dicht.\nSluit af vóór twaalven.\n— J.J.V.","note_final":"Goed opgeborgen. Morgen om negen. — J.J.V.","card_desk":{"kind":"Sage","description":"In het Centraal Sagenarchief staat een leestafel met een groen kleed, en daarop een lamp met een groene kap. Langs de muur staan vijf kasten met laden vol kaarten. 's Avonds, als de anderen weg zijn, zit daar de assistent die 's avonds doorwerkte, en leest. Men ziet alleen de handen in het lamplicht.","place":"Amsterdam","prov":"N.-H.","year":1936,"code":null,"initials":"J.J.V.","teller":"de vorige assistent","note":"Niet lezen. Opbergen."},"trail_notes":["Niet door mij opgetekend. Mijn vorige assistent.","Zelfde hand. Hij werkte 's avonds door.","Zijn laatste. Daarna geen kaarten meer van hem.","Deze heeft hij niet opgeborgen. Ik ook niet."],"card_five":{"kind":"Sage","description":"Er was eens een nieuwe assistent op het Sagenarchief die 's avonds bleef om het opbergen af te maken. De verzamelaar was naar huis gegaan. De assistent zette vier kasten op orde en maakte toen ook de vijfde open, al was gezegd dat die dicht moest blijven. Daarna is de assistent niet meer gezien. De kaarten lagen keurig op volgorde, en wat de assistent daar zag, dat was ____.","place":"Amsterdam","prov":"N.-H.","year":"tomorrow","teller":"J.J.V.","initials":"J.J.V.","code":null},"final_words":["niets","mij","mijzelf","de assistent","de vorige assistent"],"door_locked":"Op slot. De sleutel zit in de jas van J.J.V.","midnight":"De klok slaat twaalf.","good_end":"Goed gedaan. Kast vijf blijft dicht.","nee":"Nee.","not_yet":"Nog niet.","into_envelope":"In de envelop.","archive_note":"Achter het schot hoef je vannacht niet.","finish_first":"Nog niet. Eerst kast {roman}.","digit_note":"{n}. Het cijfer van kast {roman}.","digit_first":"Onthouden: het slot van kast V wil er vier.","found_notes":{"chair":"Eén ligt waar ik hem gisteren neerlegde.","lamp":"Eén ligt onder de lamp. Niet de lamp verzetten.","coat":"Eén zit in mijn jas. Jas laten hangen.","typewriter":"Eén zit nog in de machine."},"floor_note":"Die hoort niet in die la.","machine_continued":"— vervolg in la 3 —","reactions":{"reopen_filed":"Die was klaar.","stalled":"Opschieten.","read_desk":"Ik had gezegd: niet lezen.","typo3":"Het staat er. Lees.","other_hand":"hij komt niet terug","five_shut":"Dicht."},"citation":"Bron: Nederlandse Volksverhalenbank, Meertens Instituut (KNAW), www.verhalenbank.nl"},"cabinets":[{"id":1,"label":"Voortekenen","digit":2,"drawers":[{"id":"1-1","type":"P4","difficulty":1.4932,"rank":0.0287,"note":"Doorgescheurd. De rest ligt in de doos op tafel.","cards":[{"id":"c1","story_id":"CJ018502","role":"top","render":{"description":"Een vrolijke man is plotseling erg zwaarmoedig en stil. Hij verzekert zijn vrouw dat er niets aan de hand is, maar blijft somber.","place":"Sumar","prov":"Fr.","year":1967,"code":"SINSAG 0489","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/20330","half":"top"},"home":"1-1"},{"id":"c2","story_id":"CJ098901","role":"distractor","render":{"description":"Volgens de schooier kondigt een hond die op je afkomt en in je kuiten hapt een sterfgeval aan.","half":"bottom","code":"SINSAG 0486"},"home":"1-1"},{"id":"c3","story_id":"CJ065304","role":"distractor","render":{"description":"Later is er een kraamvrouw uit de buurt gestorven en vond de begrafenis echt plaats.","half":"bottom","code":"SINSAG 0483"},"home":"1-1"},{"id":"c4","story_id":"CJ082105","role":"distractor","render":{"description":"Als de helm van een helmdrager direct verbrand wordt, wordt de helmdrager niet gekweld door voorgezichten.","half":"bottom","code":"SINSAG 0481"},"home":"1-1"},{"id":"c5","story_id":"CJ110101","role":"distractor","render":{"description":"Het is een voorbode: later wordt er op die plaats een nieuw huis gebouwd.","half":"bottom","code":"SINSAG 0487"},"home":"1-1"},{"id":"c6","story_id":"CJ018502","role":"bottom","render":{"description":"Op het laatst vertelt hij zijn vrouw dat ze op het punt staan om twee kinderen te verliezen omdat hij hun begrafenis gezien heeft. Een tijdje later komt het precies zo uit. De man is met de helm geboren en kan dingen die in de toekomst staan te gebeuren voorzien.","half":"bottom","code":"SINSAG 0489"},"home":"1-1"},{"id":"c7","story_id":"CJ016802","role":"distractor","render":{"description":"Hij ziet vaak lijkstoeten passeren. De Heer verlost hem van zijn helderziendheid, omdat de jongen het er erg moeilijk mee heeft.","half":"bottom","code":"SINSAG 0481"},"home":"1-1"},{"id":"c8","story_id":"CJ013201","role":"distractor","render":{"description":"'s Middags viel er boven een groot schilderij. Het glas van het schilderij en de vaasjes op de schoorsteenmantel sneuvelden. Dat gaf hetzelfde geluid als ze 's morgens gehoord hadden.","half":"bottom","code":"SINSAG 0487"},"home":"1-1"},{"id":"c9","story_id":"CJ111605","role":"distractor","render":{"description":"Ze is erg van streek als ze sterfgevallen vooruit ziet in passerende lijkstoeten. Als ze er op een nacht uitmoet om een voorgezicht te krijgen, struikelt ze. Door de val raakt ze haar helderziendheid kwijt.","half":"bottom","code":"SINSAG 0489"},"home":"1-1"},{"id":"c10","story_id":"CJ117402","role":"distractor","render":{"description":"Als er twee eksters bij het huis zitten, komt er visite.","half":"bottom","code":"SINSAG 0486"},"home":"1-1"},{"id":"c11","story_id":"WEV001201","role":"distractor","render":{"description":"De paarden die eerst voor de lijkwagen worden gespannen weigeren, zodat het zwarte paard moet worden ingespannen.","half":"bottom","code":"SINSAG 0487"},"home":"1-1"},{"id":"c12","story_id":"CJ043710","role":"distractor","render":{"description":"Toen de kist het huis uit werd gedragen, klapte de kist tegen de muur. Dit gaf precies hetzelfde geluid als dat ze eerder gehoord hadden.","half":"bottom","code":"SINSAG 0486"},"home":"1-1"},{"id":"c13","story_id":"CJ076509","role":"distractor","render":{"description":"Het is een slecht huwelijk, hij is zeer ongelukkig, kan niet met mijn moeder overweg en wordt ziek. Hij heeft jarenlang met kanker rondgelopen. Het is diepe armoede geweest.","half":"bottom","code":"SINSAG 0489"},"home":"1-1"}],"hints":["Lees het bovenste stuk tot het laatste woord. Wat wordt er al genoemd?","Het onderste stuk noemt ‘man’ opnieuw.","Het nummer is SINSAG 0489. Er zijn er drie met dat nummer in de doos."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c6"},"on_success":{"fuse":["c1","c6"],"stack":["c1","c6"]},"found_card":null},{"id":"1-2","type":"P3","difficulty":1.1568,"rank":0.3178,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"ZEEUW056","role":"intruder","render":{"description":"'s Nachts vraagt een dame aan een stroper haar te verlossen. Ze brengt hem bij drie kisten met schatten, en stuurt hem op de grote zwarte hond af om de sleutel uit zijn bek te pakken. De man ziet dat de hond de duivel is, laat zich weer naar boven brengen, waarna hij wordt vervloekt. Hij komt ziek thuis, en blijft lang ziek. Zijn hele leven blijft hij arm.","place":"Zwartenhoek","prov":"Zl.","year":1923,"code":"SINSAG 0301","initials":null,"url":"https://www.verhalenbank.nl/items/show/38982","original":"Zwarte Dame\nMijn vadere was 'nen perser 1) gelijk da' ge weet. Altijd was hij op zoek naar 't wild, of naar de visch, of naar 't geveugelte, en of dat nou mocht, of dat het nie mocht, daar vriegen die menschen niet naar.\nIn den winter ging hij, als 't gebeurde dat er geen werk was, putters en sijzen en vinken gaan vangen met lijmstokken in het schorre, in den zomer ging hij gaan visschen in alle waters waardat visch in zat, en in t achterjaar en in den winter zette hij stroppen voor de hazen en voor de kernijnen. …","lang":"Standaardnederlands","front":"original"},"home":"cab:2"},{"id":"c2","story_id":"BIJLSMA004201","role":"member","render":{"description":"Bij kerktoren blijft hond uit angst dicht bij baas lopen; jankt bij huis van zieke tot die is gestorven.","place":"Sondel","prov":"Fr.","year":1966,"code":"SINSAG 0486","initials":"T.B.","url":"https://www.verhalenbank.nl/items/show/130455","original":"Bakker kaem mei syn jeijen en fiskjen wol folle let thús en wie sa op 'e lette joun, ja, yn 'e nacht faek noch op 'n paed.\nOp in kear hied er jage op 'e Sondeler Leijen. Yn 'e nacht gie er op hûs oan. Syn hountsje Fike wie by him. By de Sondeler toer gie er skean it lân oer nei de Noarderreed, dêr't er wenne en noch wennet. As se sa ûnderweis wiene doarme Fike by him wei, mar doe't hja dêr by de toer wiene, wie Fike net by him wei to slaen. De houn roun deun tsjin him oan, sadat Bakker hast gjin foet forsette koe. \nBakker treau de houn by him wei en sei: hwat is der, hwat skeelt der oan. Hy koe de houn net ôfwarre; hy roun him sahwat tusken de skonken. Hwat wie der, hwat hat Fike sjoen, sa freget Bakker him ôf. …","lang":"Fries","front":"original"},"home":"1-2"},{"id":"c3","story_id":"BIJLSMA001605","role":"member","render":{"description":"Enkele dagen nadat hond jankend bij zijn baas zit, sterft de man.","place":"Sintjohannesga","prov":"Fr.","year":1965,"code":"SINSAG 0486","initials":"T.B.","url":"https://www.verhalenbank.nl/items/show/130282","original":"Van der Wal syn oer-pake wie even nei de wetterfloed fan 1825 yn 'e feanderij yn it Skar ûnder Sint Jehannesgea. Dat wie yn de tiid dat der in greate stjerte wie, dat kaem mûlk fan it séwetter. Doe't er dêr yn it Skar wie mei syn houn, roun dy hieltyd foar him út en gong dan wer jammerdearlik foar him sitten to janken. Hy tocht, hwat skeelt dy houn, mar it bist wist fan gjin ophâlden en gûlde mar troch.\nTrije dagen letter wie de âld man dea.","lang":"Fries","front":"original"},"home":"1-2"},{"id":"c4","story_id":"BIJLSMA004903","role":"member","render":{"description":"Spookhuilen van een hond betekent dat er iemand zal sterven.","place":"Langweer","prov":"Fr.","year":1966,"code":"SINSAG 0486","initials":"T.B.","url":"https://www.verhalenbank.nl/items/show/130518","original":"To Eastergea by it klokhús stie alear de herberch \"Hof van Holland\". Der binne letter fjouwer wenten fan makke, dy 't der noch steane. Dêr wenne Jelle de Vries, dy hie in houn, dy koe alderôfgryslik spoekgûle. Dan gie der stéfêst immen dea. Op in kear wie it alhiel mâl hoe 't de houn gûlde. Daliks neielkoar kamen der yn dat lytse doarpke fjouwer to forstjerren.","lang":"Fries","front":"original"},"home":"1-2"}],"hints":["Kijk naar de nummers in rood potlood.","Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De kaart over Zwartenhoek hoort bij de Witte wieven."],"lock":{"kind":"card_to_cabinet","card":"c1","cabinet":2},"on_success":{"trail_note":0,"unlock_cabinet":2,"stack":["c2","c3","c4"]}},{"id":"1-3","type":"R1","difficulty":1.1137,"rank":0.1967,"note":"De klok staat stil. Deze drie weten hoe laat het is.","cards":[{"id":"c1","story_id":"CJ045808","role":"omen","render":{"description":"Bij het water wordt kindergekrijs gehoord. Het is een voorteken: later worden twee kinderen ternauwernood van de verdrinkingsdood gered.","place":"Harkema","prov":"Fr.","year":1968,"code":"SINSAG 0486","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/24335","original":"Der ha froeger twa bern fan Simen Spinder yn 't Fliet sitten. Dy binne omtrint forsûpt. Simen hat se noch kret op 'e tiid ret. Fan tofoaren ha se dy bern dêr razen heard. Dat wie foartsjirmerij.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"},{"id":"c2","story_id":"CJ027603","role":"omen","render":{"description":"Twee broers waren eens op bunzingjacht toen een van hen een doodskist met een wit kleed zag. De ander zag niets. Een wit kleed over een doodskist betekende dat diegene in de kraam was gestorven.","place":"Houtigehage","prov":"Fr.","year":1967,"code":"SINSAG 0483","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/21630","original":"Ek in kear, doe wienen wy der wer togearre op út to murdejeijen. Wy wienen achter it Dwarsdjip.\n\"Sjoch\", sei Wessel ynienen.\n\"Hwat sjochstû\", sei 'k.\n\"In kiste mei in wyt kleed der oer\", sei er.\nDan wie der ien yn 'e kream stoarn as der in wyt kleed oer de kiste lei.\n\"Ik sjoch neat\", sei 'k.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"},{"id":"c3","story_id":"CJ017911","role":"omen","render":{"description":"Twee mensen wijken uit voor een lijkstoet; korte tijd later overlijdt er daadwerkelijk iemand.","place":"Sumar","prov":"Fr.","year":1967,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/20224","original":"Ik en Wibe Weening hienen op in joun yn 'e Harkema oan 't kuijerjen west. Doe sei Wibe tsjin my: \"Mast even út 'e wei gean.\" Wy stienen in skoftsje oan 'e kant fan 'e wei. \"Nou kinne wy wol wer op 'e wei\", sei er. Hy hie in lykstaesje foarbygean sjoen. Mar ik seach neat. 't Wie Pytsje Alma har man, dêr't er de bigraffenis fan sjoen hie. Dy is koart dêrnei stoarn.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"}],"hints":["Lees ze nog eens. Ze tellen alle drie iets.","Drie keer hetzelfde getal. Zo laat is het.","2 uur. Zet de klok."],"lock":{"kind":"clock_hour","hour":2},"on_success":{"chime":2,"digit":{"value":2,"card":"c1"},"stack":["c1","c2","c3"]}}]},{"id":2,"label":"Witte wieven","digit":3,"drawers":[{"id":"2-1","type":"P1","difficulty":0.9161,"rank":0.8022,"note":"Alle vier noemen ze hetzelfde ding. Dat wordt het etiket. Niet ‘een beest’ schrijven.","cards":[{"id":"c1","story_id":"LYST276","role":"card","render":{"description":"Stiepelteken is ontstaan toen een wit wief de bijl waarmee ze een boerenknecht achtervolgde, in de deurpost van de schuurdeur terecht kwam. De boerenknecht had de witte wieven uitgedaagd door bij een spinvisite een spit te brengen, en er meteen weer vandoor te gaan.","place":"Vasse","prov":"Ov.","year":1937,"code":"SINSAG 0161","initials":"B.J.L.","url":"https://www.verhalenbank.nl/items/show/13620","original":"Op veel plaatsen in Twente hoort men de volgende vertellingen.\nDe Witte Wiefkes hadden eens gasten of spinvisite. De knecht van een boer uit de buurt bracht er het spit heen; en toen als de wind weer terug naar huis te paard. Maar een der witte wiefkes zat hem met een bijl achterna. De knecht was echter eerder thuis. Zij wierp hem echter met de bijl na, die in den stipel (deurstijl achterdeur) bleef zitten en toen riep ze nog: \"Had ik mien eenen schoen zo gauw knupt als m'andren rupt, dan was doe 't gebraad west.\"","lang":"Standaardnederlands; Twents","front":"description"},"home":"2-1"},{"id":"c2","story_id":"LYST280","role":"card","render":{"description":"Een boerenknecht loopt 's nachts langs de Witte Wieve. Omdat hij hen beledigt, achtervolgt een van hen hem. De knecht kan net een huis binnenvluchten. De bijl die het Witte Wief gooide komt terecht in de stiepel.","place":"Goor","prov":"Ov.","year":1937,"code":"SINSAG 0161","initials":"J.W.L.","url":"https://www.verhalenbank.nl/items/show/13624","original":"Witte Wieven waren hier bekend. Men geloofde dat ze ongeluk aanbrachten.\nEen verhaal gaat hier, dat een boerenzoon laat naat huis terugkeerde en langs een plek kwam, waar een wit wief een gebraad aan het spit ronddraaide. De boerenzoon beledigde haar, waarna het witte wief hem met een bijl achterna zette. Gelukkig voor de boerenzoon kon hij nog net de boerderij bereiken, voor het witte wief hem had ingehaald. Maar deze gooide hem nog de bijl achterna, die in de \"stiepel\" bleef zitten.","lang":"Standaardnederlands","front":"description"},"home":"2-1"},{"id":"c3","story_id":"LYST075","role":"card","render":{"description":"Op een bruiloft merkt een van de gasten op dat ze zijn vergeten de witte wieve uit te nodigen. Wanneer iemand spottend de witte wieve roept, wordt er een bijl naar zijn hoofd gegooid. Hij kan net op tijd naar binnen vluchten. De deur vertoont nog altijd de tekenen van de bijl. Het witte wiefke roept dat ze hem wel te pakken had kunnen nemen, als ze haar schoentje niet was verloren.","place":"Zenderen","prov":"Ov.","year":1953,"code":"SINSAG 0161","initials":"M.S.","url":"https://www.verhalenbank.nl/items/show/13289","original":"Parallel met het verhaal van de \"spinvisite\" loopt ook 't verhaal van de \"brulfte\" (bruiloft) waar een van de gasten tegen de \"brulfteneugers\" opmerkt dat hij de \"nögste noabers\" n.l. de \"witte wieve\" heeft vergeten. De \"brulfteneuger\" laat dat niet op zich zitten, gaat naar buiten en nodigt \"de witte wieve\" uit, op spottende toon. Hij wordt onmiddelijk achterna gezeten, vlucht nog net binnenshuis, terwijl hem de bijl nagegooid wordt en 'n snee in de niendeure maakt die nog aan de kleinkinderen van het bruidspaar vertoond wordt. Hier hoort ook weer dezelfde klacht over 't schoentje bij, dat niet was vastgestrikt.","lang":"Standaardnederlands","front":"description"},"home":"2-1"},{"id":"c4","story_id":"ENGELB_13_014","role":"card","render":{"description":"Man die het spit naar berg van de Hunnen brengt wordt daarna achtervolgt door een Hun met een bijl. De man kan de boerderij binnengaan, de Hun gooit hem de bijl na, die in de deurpost terechtkomt.","place":"Rossum","prov":"Ov.","year":1977,"code":"SINSAG 0161","initials":"H.E.","url":"https://www.verhalenbank.nl/items/show/128541","original":"Spit brengen\nG.M.: Ja dee knecht van Scholtn möt dat doan hebn, den hef t spit doar op n Huunboarg bracht en den hef t peard bie zik had en tenminste zoa heb ik t wa es heurd verteln en doe hef he t spit hef he doar henbracht noa n Huunboarg en doe is het der tuskn oet goan, n Huun löaw’k noa met t haandbiel en doe is Schoolt zien knecht bie t Schoolt owwer n onderstn nienduur vlögn en doe hef n Huun hem nog noasmetn en t haandbielkn in in duurnpost smetn\nE.M.: Dat heb ik ok vaak heurd.\nG.M.: Zoa heb ik t vaak heurn verteln.\nE.M.: A’j dat oppervlakkig bekiekt, zo’j zegn. Dat kan hoast geelsnich, mer ja ik heb wa honderd moal heurn verteln.","lang":"Twents","front":"description"},"home":"2-1"}],"hints":["Lees de vier nog eens. Let op wat er in elk van de vier vóórkomt, niet op wat erin gebeurt.","Het is een voorwerp.","Begint met een B. 4 letters."],"lock":{"kind":"word","salt":"0eec280b8b12db04","accepted_hashes":["7a4d4682a43a5d8efcdd802c056e4da17a094ea95a128de0a2618693b52db0fe","eaa17932fe07f388e1a76dbf99d5289749d9f4bd19ba7b2b0969a71fbd47f935"]},"on_success":{"print_label":true,"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c4"}},{"id":"2-2","type":"P3","difficulty":1.0633,"rank":0.4745,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"KOOIJMAN0296","role":"member","render":{"description":"Bij 't Slot spookten witte dames. Veel mensen durfden vanwege hen niet in de buurt te komen.","place":"Tienhoven","prov":"Utr.","year":1962,"code":null,"initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/50997","original":"Bij 't Slot* spookte 't altijd. D'r liepen dames in het wit. Een hoop mensen, die d'r niet heen dorsten.\n\n*Ameide","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c2","story_id":"CJ053309","role":"member","render":{"description":"Een man ziet 's nachts plotseling twee witte vrouwen. De twee vrouwen nemen plaats op zijn wagen. De man wordt zo bang, dat hij er snel vandoor gaat.","place":"Ons Belang","prov":"Utr.","year":1968,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25339","original":"Hjir ien út 'e Harkema ried us mei de boerewein op in nacht nei Readskuorre ta. Doe seach er dêr ynienen twa wite froulju foar him. Hy ried dêr mei de hynders lyk op yn.\nDoe kommen dy beide froulju yn 't wyt by him op 'e wein.\nHy woarde sa binaud, dat hy sette sokken en naeide út.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c3","story_id":"KOOIJMAN1499","role":"intruder","render":{"description":"Vroeger hadden we een buurman en daar werd van gezegd dat hij kon weerwolven. Mensen waren bang voor hem.","place":"Herwijnen","prov":"Gld.","year":1963,"code":null,"initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/125634","original":"Heel vroeger woonde d'r een buurman naast ons. Die kwam van Kuilenburg. Toen ging die naar Waardenburg. Daar wier gezeed, dat ie kon weerwolve. Die ken weerwolve. Hij stond d'r voor bekend in Waardenburg. De jongens rende d'r voorbij.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"cab:3"},{"id":"c4","story_id":"CJ063612","role":"member","render":{"description":"In Almelo hebben ze witte wijven en er spookt een mooie vrouw. Dat heb ik gehoord toen ik daar paarden kocht.","place":"Soesterberg","prov":"Utr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/27090","original":"In Almelo hebben ze witte wiven. En daar spookt ook nog een mooie vrouw om. Ik heb het daar wel eens gehoord toen ik daar peerden kocht.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"2-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een weerwolf.","De kaart over Herwijnen hoort bij de Weerwolven."],"lock":{"kind":"card_to_cabinet","card":"c3","cabinet":3},"on_success":{"trail_note":1,"unlock_cabinet":3,"stack":["c1","c2","c4"]}},{"id":"2-3","type":"R2","difficulty":1.0353,"rank":0.4407,"note":"Er staat iets op het raam. Niet afvegen.","cards":[{"id":"c1","story_id":"ZEEUW051","role":"card","render":{"description":"Op Grauw gebeurde het soms, als je 's avonds laat op pad ging, dat je gezelschap kreeg van de Witte Juffer.","place":"Graauw","prov":"Zl.","year":1921,"code":"SINSAG 0310","initials":"L.L.","url":"https://www.verhalenbank.nl/items/show/38977","original":"Witte Juffers\n\nOp Grauw gebeurde het soms, als ge 's avonds laat op pad ging, dat ge gezelschap kreegt van de Witte Juffer.","lang":"Standaardnederlands","front":"description"},"home":"2-3"},{"id":"c2","story_id":"TINNEV038","role":"card","render":{"description":"Een man sluit een weddenschap af, dat hij het 'witte wief' uit het bos ten dans durft te vragen. Ze dansen totdat de man niet meer kan en dood neervalt.","place":"Didam","prov":"Gld.","year":1944,"code":"SINSAG 0310","initials":"A.T.","url":"https://www.verhalenbank.nl/items/show/22384","original":"25. DE WITTE WIEF VAN MONTFELAND\nIen de bös rond Montfeland zitte witte wief die gin mins kwaod doen, ai eur teminste met rös laot. \nIemand uut Beak, dén met 'n zatte kop aan zon wief vroeg of ze met um wol danse, kosse die vroag 't lève. Zi'j bleef de hele nach met um aan 't deurdanse. De man wol iedere kier opholle, mao dat \nging niet. Hi'j mos deurdrèje, ook toe te nie meer kon. 't Zweit liep um nèven 't lief as offe ien de bare zon aan 't rogmèje was. Hi'j smeken um toch op te holle, mor 't wief ging deur. Endelijk, ien de margetied, viel de man dood veur eur vuut neer. …","lang":"Liemers","front":"description"},"home":"2-3"},{"id":"c3","story_id":"YPFOE070d","role":"card","render":{"description":"De verteller gaat met een paar vrienden op huis aan. Onderweg komen ze een wit meisje tegen dat zich snel voortbeweegt. Ze zweeft in de richting van een huisje. Ze gaan op onderzoek uit. Later heeft zich een oude man opgehangen, en men zegt dat het ermee in verband staat. De dominee staat erg sceptisch tegenover het verhaal.","place":"Goutum","prov":"Fr.","year":1972,"code":"SINSAG 0310","initials":"Y.P.","url":"https://www.verhalenbank.nl/items/show/12149","original":"Wite juffers\nWat ik hjir yn 'e Westerein sels sjoen ha. Dat is no lyn, ik tink sa'n fiif-, seis-, sânenfyftich jier. Myn kammeraat en ik gyngen de jûntiid om in oere of alve stadichoan nei hûs ta. Doe troffen wy in pear jongelju en dy hâlden ús oan. De man sei: 'Sjoch, wat is dêr? Dêr is in famke midden yn 'e sûkerei. By it hûs dêre is it allegearre út en tsjuster, mar hoe kin dan sa'n wyt famke der yn 't lân weze?' Doe seach ik it ek. Ik sei: 'Dan moatte wy dêr ris even sjen'. Mar dat famke avensrarde tige hurd en wy koenen sjen, dat it net gie, mar dat it sweefde. It hie de grutte sawat fan in gewoan famke, en sniewyt. Ik sei: 'No, sille wy ris sjen? …","lang":"Fries","front":"description"},"home":"2-3"},{"id":"c4","story_id":"ENGELB_08A_001","role":"card","render":{"description":"Woonplaats van witte wieven, zijn behulpzaam, als ze met rust worden gelaten doen ze niets.","place":"Mander","prov":"Ov.","year":1974,"code":"SINSAG 0310","initials":"H.E.","url":"https://www.verhalenbank.nl/items/show/128452","original":"Bels: Doar hebt ze ok wat vuindn, nich, doe ze doar vrower an 't bouwn warn west, nich, en an 't eand har der dan nen kôm koffie of melk, dee har der kloar stoan zoa vertöln ze van oolds oet, nich.\nIk: Woar hebt dee witte wiew dan eigenlik in lewd dan?\nB: Dee hebt in de holn lewd.\nIk: Was dat een of andre beult, woar at ze inzatn?\nB: Joa ze zatn in ne beult, dat warn twee beultn, dee hebt ze later nog ôpgrövn, dokter Hijszeler is der wa met an 't grewn west met dee beultn, nich? …","lang":"Twents","front":"description"},"home":"2-3"},{"id":"c5","story_id":"CJ018012","role":"sill","render":{"description":"Op een spookplaats spoken altijd drie witte dames, zusters, rond. Later zou die plaats ook de 'Susterwei' heten.","place":"Garyp","prov":"Fr.","year":1967,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/20251","stain":"drie"},"home":"2-3"},{"id":"c6","story_id":"WEV014306","role":"card","render":{"description":"Huis waarin witte juffers lopen durft niemand te kopen.","place":"Meerland","prov":"Gr.","year":1966,"code":"SINSAG 0310","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44759","original":"Bie Appingedam ston eerder n hoes, woor t in spookde.\nZai zaggen er widde juffers in loopn.\nEt is n poar keer te koop aanboden, moar gainaine dus t koopn. \nHou of t er loater mit goan is, wait ik nait.","lang":"Gronings","front":"description"},"home":"2-3"}],"hints":["Lees het van achteren naar voren.","Het begint met een G.","Garyp. Leg die kaart op de vensterbank."],"lock":{"kind":"card_to_object","card":"c5","object":"window","text":"Garyp"},"on_success":{"digit":{"value":3,"card":"c5","word":"drie","stained":"c5"},"stack":["c1","c2","c3","c4","c5","c6"]}}]},{"id":3,"label":"Weerwolven","digit":7,"drawers":[{"id":"3-1","type":"P2","difficulty":3.1399,"rank":0.219,"note":"Zonder plaats. Ergens tussen de andere drie. Prik hem op de kaart.","cards":[{"id":"c1","story_id":"LINSSEN009612","role":"target","render":{"description":"Weerwolf laat zich dragen; meisje zou zich in weerwolf kunnen veranderen.","place":null,"prov":"L.","year":1965,"code":"SINSAG 0801","initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208996","original":"Weerwolf . \"Oom Toon\" had de weerwolf gezien. Hij zag eruit als een half kaalgeschoren hond. Twee keer had hij hem moeten dragen tot waar de huizen van Putbroek stonden. In Montfort zou een meisje zich in een weerwolf hebben kunnen veranderen.","lang":"Standaardnederlands","front":"description"},"home":"3-1"},{"id":"c2","story_id":"LINSSEN001602","role":"helper","render":{"description":"Iemand vreest dat de weerwolf op zijn rug zal springen, en hoort tijdens het wegrennen het schuren van zijn eigen broekspijpen langs elkaar en dat klinkt als het roepen dat hij gepakt moet worden. Hij heeft er de bijnaam Frans Vattem aan overgehouden.","place":"Maasbracht","prov":"L.","year":1962,"code":"SINSAG 0801","initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208281","original":"Weerwolf. Een eenvoudige landbouwer in de Brachter beek was nogal angstig aangelegd. Hij meende dat de weerwolf hem op de hielen had gezeten. Op een avond was hij op weg geweest op een vrij eenzaam pad tussen Brachterbeek en Maasbracht, toen hij opeens achter zich hoorde:\"Vat hem\", \"Vat hem\" Hoe sneller hij liep, hoe vlugger de roep. Bij de Mispadenhof gekomen sprong hem de weerwolf op de rug. Hoe dat verder gegaan was vermeldt de geschiedenis niet. Wel weet men een verklaring te geven van de stem die hij hoorde. Hij droeg namelijk een Manchester broek met ribbels. Hoe sneller hij liep, hoe vaker de broekspijpen langs elkaar schuurden, hoe sneller en hoe sneller de roep: \"Vat hem\". \nHij heeft later de naam Frans Vattem gehouden.","lang":"Standaardnederlands","front":"original"},"home":"3-1","geo":[51.13929,5.88627]},{"id":"c3","story_id":"LINSSEN005701","role":"helper","render":{"description":"Weerwolf wil op rug van vrouw springen, verdwijnt na geschreeuw.","place":"Wessem","prov":"L.","year":1963,"code":"SINSAG 0801","initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208582","original":"Weerwolf: Bij Stèveke, een wessemer inwoner, lag voor het huis een grote vierkante steen. Daarachter zat op zekere avond een weerwolf verborgen. Een vrouw die daar passeerde, schrok plotseling toen het ondier op haar afkwam en haar op de nek sprong. Zij holde uit alle macht weg in de richting van de Steenweg. Daar stond juist de \"kromme boer\", leunende op de benedenste helft van een in tweeën gedeelde staldeur. Hij liet een schreeuw, de weerwolf voelde zich bedreigd en verdween in de duisternis.","lang":"Standaardnederlands","front":"original"},"home":"3-1","geo":[51.15954,5.88146]},{"id":"c4","story_id":"LINSSEN007303","role":"helper","render":{"description":"Zien van lichten, waarschijnlijk ogen van weerwolf, want man moet even late weerwolf dragen.","place":"Melick","prov":"L.","year":1964,"code":"SINSAG 0801","initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208780","original":"Dwaallichten: Een man uit Broeksittard, later wonende te Melick, ging 's avonds vaak naar Roermond, naar Kapel in het Zand. Van daaruit nam hij een binnenweg naar Melick toe. Op zekere avond zag hij in het donker twee scherpe lichten, die hij dan links dan rechts van de weg zag. Op een gegeven moment waren zij verdwenen. Maar hij voelde plotseling een last op zijn rug. Zijn borst werd omklemd door een paar armen of poten. Bij het dorp werd hij losge;aten. Hij had de weerwolf gedragen. De lichten waren waarschijnlijk de glinsterende ogen van de weerwolf geweest.","lang":"Standaardnederlands","front":"original"},"home":"3-1","geo":[51.15917,6.01667]}],"hints":["Drie plaatsen staan er al. De vierde ligt daartussen.","Binnen 2 uur lopen van Melick.","Zoek Putbroek op de kaart."],"lock":{"kind":"place","target_geo":[51.09667,5.9875],"radius_km":6.0},"on_success":{"fill_field":{"card":"c1","field":"place","value":"Putbroek"},"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c4"}},{"id":"3-2","type":"P3","difficulty":1.2646,"rank":0.814,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ084112","role":"member","render":{"description":"Één van zeven meisjes is een nachtmerrie en één van zeven jongens een weerwolf.","place":"Rottevalle","prov":"Fr.","year":1971,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/32830","original":"Se sizze fan 'e sawn famkes út ien húshâlding is ien in nachtmerje en fan 'e sawn jonges út in húshâlding is ien in wearwolf","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c2","story_id":"HOL002419","role":"intruder","render":{"description":"Uiterlijk en handelingen van weerwolven.","place":"Opheusden","prov":"Gld.","year":1964,"code":null,"initials":"A.R.H.","url":"https://www.verhalenbank.nl/items/show/210126","original":"Dirk Winsen vertelde: \"Hij ister vannach weer gewes\" Hij was een weerwolf. Weerwolven liepen \"op-te-vier\" nl. op handen en voeten. Men kon dit aan hun vingers zien, want ze hadden \"zwil (= eelt) opte kneukels\" (= gewrichten). Ze hadden een \"vel\" om, dat ze ergens vandaan haalden. Waarvandaan wist R. niet. Ze lieten een brommend geluid horen en hadden vurige ogen. Om twaalf uur moesten ze er op uit om te gaan \"wèrwolve\". Hun lichaam mocht dan nog wel op het bed liggen, maar de geest was er uit, die was bezig het de mensen lastig te maken, Ze liepen de late wandelaars voor de voeten, gooiden mensen met kar en paard van de dijk, maar wat een geluk was: er bleek na deze behandeling niets gebroken. Plotseling kwamen de weerwolven tegen de dijk op. …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"cab:4"},{"id":"c3","story_id":"CJ101519","role":"member","render":{"description":"Een van zeven dochters is een nachtmerrie; een van zeven zonen is een weerwolf.","place":"Drachtstercompagnie","prov":"Fr.","year":1973,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/36981","original":"Ien fan sawn famkes út ien gesin wie in nachtmerje.\nIen fan sawn jonges út ien gesin wie in wjerwolf.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c4","story_id":"CJ085401","role":"member","render":{"description":"Een van zeven broers is een weerwolf. Als hij weer een kuur heeft, moet men hem een oud schort of iets toewerpen. Dat verscheurt hij dan. Als men iemand met de draden uit zijn mond ziet, kan men ervan opaan dat dat een weerwolf is.","place":"Rottevalle","prov":"Fr.","year":1971,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/33002","original":"In wearwolf is in minske, dy forropt de boel. 't Is ien fan sawn jonges (7 bruorren). As er wer sa'n kuer krijt, dat er hwat forskuorre mat, mat men him in âld skelk of sahwathinne tasmite. Us mem sei, dan gebeurde 't wol dat him even letter de triedden ta de mûle úthongen.\nAs men sa'n ien seach, dy't triedden ta de mûle út hie, koe men der fan op oan dat it in wearwolf wie. Dêr koe men se oan herkenne.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"3-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een spook.","De kaart over Opheusden hoort bij de Spoken."],"lock":{"kind":"card_to_cabinet","card":"c2","cabinet":4},"on_success":{"trail_note":2,"unlock_cabinet":4,"stack":["c1","c3","c4"]}},{"id":"3-3","type":"R3","difficulty":1.0756,"rank":0.6667,"note":"Als er geklopt wordt: tel. Die kaart onder de deur.","cards":[{"id":"c1","story_id":"KOOIJMAN1182","role":"card","render":{"description":"Er woonde vroeger in Blokland een vrouw en die beweerde dat ze iedere avond de weerwolf buiten tekeer hoorde gaan tussen half elf en twaalf uur.","place":"Blokland","prov":"Utr.","year":1963,"code":"SINSAG 0804","initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/72678","original":"De weerwolf, de weerwolf. Nou je 't zegt. D'r woonde vroeger in Blokland een vrouw. Die woonde daar op d'r eige alleen. En die vrouw die beweerde, ze hoorde iedere avond de weerwolf buite tekeergaan. Iedere avond tusse half elf en twaalf uur. Ze sloot alles d'r voor af.","lang":"Utrechts","front":"description"},"home":"3-3"},{"id":"c2","story_id":"CJ096724","role":"door","render":{"description":"Een op de zeven broers is een weerwolf. Weerwolven verscheuren en doden alles wat ze tegenkomen. Men moet hem daarom iets, bijvoorbeeld een doek of een bal, toesmijten waar hij zijn tanden in kan zetten.","place":"Buitenpost","prov":"Fr.","year":1973,"code":"TM 3107","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/36156","original":"In wearwolf is in man dy't alles forskuort. Ien fan sawn bruorren dy't op elkoar folgje is in wearwolf. De wearwolf makket alles dea as er de kâns kriget. Men mat him sokke tiden hwat tasmite: in doek of in bal ofsa, dêr't er de tosken yn sette kin.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"},{"id":"c3","story_id":"CJ071310","role":"card","render":{"description":"Een van acht zoons was een weerwolf. Een weerwolf kon zich nooit vol eten, hij had altijd nog honger.","place":"Houtigehage","prov":"Fr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/28045","original":"As der acht jonges wienen, dy't op elkoar folgen yn in húshâlding, dan wie ien fan dy acht in wjerwolf. Dat wie ien dy't noait sêd koe, dy't neat fan ûnpas kom.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"},{"id":"c4","story_id":"EDJSL012","role":"card","render":{"description":"Een dagloner keert terug naar huis en ziet een ploeg zonder paard of man op zich af komen. De ploeg verandert van gedaante: het is de keuterboer, die voor hem staat. De keuterboer smeekt de man hem niet te verraden. \nIn de hooitijd werken de twee mannen samen. Als de keuterboer slaapt komt er een mol uit zijn nek. De keuterboer kotst liters bloed. In de wei worden de resten van een kalf gevonden; alleen een paar afgekloven botten zijn over. De keuterboer sterft. De pastoor moet erbij komen om de kist naar het kerkhof te kunnen dragen.","place":"Didam","prov":"Gld.","year":1980,"code":"SINSAG 0804","initials":"E.d.J.","url":"https://www.verhalenbank.nl/items/show/9514","original":"Mol, de weerwolf\nEen keuterboer, die Mol heette, werd altijd uitgescholden:\n\"Bierpoep! Twee emmers vol snijbonen en nog maar wind!\"\nDat kwam omdat hij zoveel at.\nKarels, een dagloner, keerde 's avonds laat dwars door het veld terug naar huis, toen hij een ploeg zonder paard of man op zich af zag komen. Hij trok zijn mes, maar het ketste af op het ploegijzer. De ploeg veranderde van gedaante, en in de man die voor hem stond, herkende hij Mol.\nDeze viel op zijn knieën en smeekte hem niet te verraden. Hij zou Karels een mud boekweit en een mud rogge geven.\n\"Van jou, weerwolf, wil ik geen boekweit of rogge,\" zei de boerenknecht. …","lang":"Standaardnederlands","front":"description"},"home":"3-3"},{"id":"c5","story_id":"VVUNL049","role":"card","render":{"description":"Elke avond na het eten gaat Sjang weg en komt pas heel laat terug. Op een keer volgen ze hem en zien hem iets uit een boom halen en even later was hij een weerwolf. De pastoor wordt gehaald en Sjang moet zijn spullen tevoorschijn halen. Er kwam een schapevacht en een rood stokje met rood lint uit; die worden in de oven verbrand, terwijl drie man Sjang in bedwang houden. Als alles verkoold is, zegt hij verlost te zijn.","place":"Kessel","prov":"L.","year":1952,"code":"SINSAG 0824","initials":"J.N.","url":"https://www.verhalenbank.nl/items/show/35588","original":"De geplaagde herder \n\n't Gebeurde op 'Gravenhof' te Kessel, tussen 1860 en '70. Sjang van de Maas uit Neer was hier scheper; een onnozele, rustige kerel, die niemand kwaad deed, en elke dag zijn schapen hoedde. Maar na een tijdje maakten de boer en de boerin zich over hem ongerust. Elke avond na het eten verdween Sjang plotseling en keerde pas heel laat in de nacht weer huiswaarts. Dit werd zo verdacht dat men op een keer de knaap stilletjes achtervolgde... Men zag toen dat hij tot de holle boom liep, even voorbij het Annakapelletje; daar nam hij iets uit. Na enkele ogenblikken veranderde hij van gedaante, en stoof als schrikaanjagende weerwolf met een geweldige vaart weg. . . …","lang":"Standaardnederlands","front":"description"},"home":"3-3"}],"hints":["Wacht op het kloppen. Tel het.","Een oneven getal.","7 keer. Die kaart."],"lock":{"kind":"card_to_object","card":"c2","object":"door","n":7},"on_success":{"digit":{"value":7,"card":"c1"},"stack":["c1","c3","c4","c5"]}}]},{"id":4,"label":"Spoken","digit":4,"drawers":[{"id":"4-1","type":"P6","difficulty":3.3499,"rank":0.9535,"note":"Elk verhaal één getal. In deze volgorde.","cards":[{"id":"c1","story_id":"CJ053702","role":"clip1","render":{"description":"Twee mannen die met elkaar praten blijken hetzelfde beleefd te hebben: als ze zich bij een nachtelijke boottocht aan een paal vastklampen, raken ze een witte gedaante aan. Het is een spookverschijning zonder lichaam. De gedaante spoedt zich vervolgens achter de heg langs naar de schuurdeur.","place":"Boornbergum","prov":"Fr.","year":1968,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25401","original":"Ik praette ris mei in keardel, dy sei: Dêr ha wy hwat bileefd! Wy wurken yn 'e polder. Mei de Feanster boat moest ik fuort by nacht. Ik moest troch hekken.\nIk wie by in hekke. Dêr wie in omstap neist. Ik krige de peal beet, doe taestte ik mei de hân op hwat.\n't Wie in gedaente yn 't wyt, dêr hie 'k op taest.\nFan kleare bare skrik haw ik der op houd mei de bôlleskeppe, dy't ik by my hie. Ik ha der gewoan trochhinne slein. Der siet gjin lichem oan. Doe bin 'k werom stapt.\nDe gedaente stapte achter de hage del en dy is ta de skûrdoar yn stapt.\nDoe't ik goed en wol op 'e boat wie, doe wie dêr ien op 'e boat, dy wie foar my itselde paed lâns kom.\nIk sil wol forbouwereard west ha en hwat wyt om 'e noas.\nDy oare sei tsjin my: \"Hwat sjochstû nuver. …","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c2","story_id":"CJ115905","role":"clip2","render":{"description":"Op een bepaalde plaats springt een hek steeds open: een spookhek. Twaalf mannen die 's nachts beurtelings proberen het hek dicht te duwen, zien het hek steeds weer openspringen. Vroeger is er op die plaats iemand vermoord. De geest van de dode doolt nog rond en opent het hek steeds.","place":"Eastermar","prov":"Fr.","year":1977,"code":"SINSAG 0450","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/31213","original":"Op Bennema-state to Hurdegaryp stie de hekke altyd iepen. In kloftsje fan tolve man, dy kommen hjir út 'e omkriten wei, dy woenen dêr mear fan wite. Dy gongen dêr yn 'e nacht hinne en hâldden in weddenskip.\nIen foar ien dienen se de hekke ticht. Mar net sadra hie ien de hekke ticht dien of hy sprong direkt wer iepen. Deselde dy't it ús heit forteld hat wie ien fan 'e tolve. Hy wie de earste. As er de lêste west hie, sa fortelde er, dan hie er it net dwaen doarst. Sadra't er wer by de oare alve mannen stien hie wie de hekke samar út himsels tichtklapt.\nDêr moat ris ien formoarde woarn wêze. Dyselde fynt gjin rêst, en dwaelt dêr sûnt altyd om. Dan giet de hekke iepen, as er ticht is.","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c3","story_id":"CJ081906","role":"clip3","render":{"description":"Een turfschipper die steeds opgeschrikt wordt door een naakt kindje achter het schip raadpleegt de dominee. De dominee vraagt het kind - dat allang overleden is - waarom het geen rust kan vinden. Het kind blijkt op die plaats verdronken en vervolgens zonder doodskleed begraven te zijn. Het kind verzoekt de dominee de middelste van drie vrouwen om een doodshemd te vragen. De wens wordt vervuld en de dominee reikt het kind het doodskleed aan met een houten lepel. Nu de wens van het kind vervuld is vindt het rust.","place":"Dokkum","prov":"Fr.","year":1970,"code":"SINSAG 0402","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/32618","original":"In Ternaard woonde in turfskipper. Alle kearen as dat skip daar lei dan kwam der in naken kiendsje achter bij 't skip op. De skipper wist niet hoe hij daar mee aan moest. Toen is hij naar doomny gaan en het hem fraagd wat dat was.\nDe doomny kwam op it skip en dy het bidden en hy het it kiend fraagd hwerom it geen rust hat.\nToen het dat kiend seid, hy had gjin bjirhemdtsje.\nHy was daar ferdronken en nu kon hy daar niet rusten.\nIt kiend sei: \"Over it pypke sullen drie dames lopen.\"\nDe middelste moesten se fragen om in bjirhemdsje.\nToen het de skipper henengaan en die het die middelste dame daar om fraagd. En hy het it kregen. En doe het er dat op it turfplak neergooid.\nEn doe het de doomny dat himdtsje dat kiend toereikt met een houten sleef. …","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c4","story_id":"CJ058602","role":"inside","render":{"description":"Het Jankemeer en het Trientsjemeer liggen vlak bij elkaar. In het Jankemeer heeft ene Janke zich verdronken, omdat haar vriend de verkering uitgemaakt had. In het Trientsjemeer is ene Trientsje verdronken. Mensen hebben toen geluiden gehoord. Daar spookt nog altijd een man met een witte rug in een vestje.","place":"Boornbergum","prov":"Fr.","year":1969,"code":"TM 2601","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/26058","original":"By de Skieding hienen jo twa dobben. Oan 'e iene kant fan 'e wei wie de Janke-dobbe, oan 'e oare kant de Tryntsje-dobbe.\nDer wie in sekere Janke, dy hie in feint. Dy feint hie de forkearing mei har út makke, en doe hat Janke har dêr forsûpt. Sa hat dy dobbe de namme fan Janke-dobbe krigen. Sûnt hja har dêr forsûpt hat, spoeket it dêr.\nYn 'e oare dobbe ha se in sekere Tryntsje forsûpt. Tryntsje hat doe lûd jown. Letter hearden se dêr altyd lûden. In man mei in wite rêch yn 't festje spoeket dêr noch altyd om.","lang":"Fries (Woudfries)","front":"original","note":"Deze bewaar ik apart."},"home":"4-1"}],"hints":["Elk verhaal telt.","Het eerste getal is 2.","2 — 12 — 3."],"lock":{"kind":"number3","salt":"0eec280b8b12db04","accepted_hashes":["b7ab9fd4c8ff1ed4d0ab4cd52e3b8b134cc713e4947d72a6b44ab3103fbfb83b"]},"on_success":{"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"4-2","type":"P3","difficulty":1.3555,"rank":1.0072,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ000413","role":"member","render":{"description":"Veulen met een pappot om de hals, doet niemand kwaad.","place":"Nijega","prov":"Fr.","year":1965,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/11552","original":"Yn Aldegea roan in fôlle om mei in brijpot om 'e hals. Guon dy't de reden delgongen by de Opperbuorren ha him wol sjoen. Mar hy die net ien kwea.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c2","story_id":"CJ044202","role":"member","render":{"description":"Op een bepaalde plek spookt een veulen met een brijpot om zijn nek.","place":"De Tike","prov":"Fr.","year":1968,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/24085","uncatalogued":true},"home":"4-2"},{"id":"c3","story_id":"CJ110804","role":"member","render":{"description":"Op een spookplaats doolt een paard rond met een veulen in de bek. Het zijn spookdieren.","place":"Opeinde","prov":"Fr.","year":1974,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/29615","original":"Yn 'e Rottefalle spûke froeger in hynder mei in fôlle yn 'e bek. Der kaem dêr in famke út 'e jounsskoalle, dat fleach sûnder klompen oan nei hûs ta.\n\"Hwat skeelt dy?\" frege har heit.\n\"It hynder siet my achternei mei de fôlle yn 'e bek\", sei se. Dit is al hiel lang lyn.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c4","story_id":"CJ111716","role":"intruder","render":{"description":"Op een spookplaats doolt een groot beest rond met oplichtende ogen. Je ziet het dier niet alleen aankomen, je hoort het ook aankomen omdat zijn poten klinken als paardenhoeven met hoefijzers. Als het dier nadert, moet je je snel uit de voeten maken omdat je anders weggesmeten wordt. Het dier is de duivel. Als je het duivelsdier een broodkorst toewerpt over je linkerschouder, gaat het weg. Veel nachtelijke wandelaars hebben een broodkorst op zak.","place":"Kollumersweach","prov":"Fr.","year":1974,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/29927","original":"Der spûke in swarte houn tusken Feankleaster en Twizel op it Wyldpaed. It wie in great beest, mei egen yn 'e kop as koallen fjûr. 't Waerd der ljocht fan yn 't tsjuster, as hy der oan kaem. Men koe him altyd oankommen hearre, hwant syn poaten klapten krekt as dy fan in hynder. Noait liker as sieten der hoefizers ûnder, sa hearde it.\nDer binne wol guon dy't him sjoen ha.\nKaem hy der oan, dan moesten se fan 'e wei gean, oars waerden se der wei smiten. It wie de duvel sels. As se him in breakoarste tasmieten oer 't linker skouder hinne, dan gong er fuort. De measte minsken hienen nachts as se der op út moesten, in breakoarste by har yn 'e bûse.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"cab:5"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over de duivel.","De kaart over Kollumersweach hoort bij de duivel."],"lock":{"kind":"card_to_cabinet","card":"c4","cabinet":5},"on_success":{"trail_note":3,"unlock_cabinet":5,"stack":["c1","c2","c3"]}},{"id":"4-3","type":"R4","difficulty":1.2229,"rank":0.875,"note":"Als de machine begint: laten uittikken. Het vervolg zit hierin.","cards":[{"id":"c1","story_id":"CJ062011","role":"top","render":{"description":"Iemand woont in Harkema en als hij 's laat van de boer komt, ontmoet hij altijd een oud vrouwtje op het pad die hij gedag zegt.","place":"Harkema","prov":"Fr.","year":1969,"code":"SINSAG 0450","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/26947","half":"top"},"home":"4-3"},{"id":"c2","story_id":"KEMP263","role":"half","render":{"description":"Die zegt dat het broertje aan de geest moet vragen wat er aan de hand is. En het antwoord luidt dat de jongen vijfentwintig jaar te vroeg gestorven is door de steekpartij. Zijn ziel moet al die jaren rond blijven spoken tot de tijd om is. De pastoor gebiedt om de geest in een aparte kamer op te sluiten die de komende vijfentwintig jaar niet meer geopend mag worden.","half":"bottom","code":"SINSAG 0450"},"home":"4-3"},{"id":"c3","story_id":"CJ109412","role":"half","render":{"description":"De dominee slaat de bijbel open en legt een sleutel van het huis op een zekere tekst. De volgende ochtend is de sleutel gedraaid in de richting van de appelboom. Daar blijkt een vermoord kind te zijn begraven. Nadat het kind is herbegraven op het kerkhof is het spoken opgehouden.","half":"bottom","code":"SINSAG 0450"},"home":"4-3"},{"id":"c4","story_id":"CJ030711","role":"half","render":{"description":"Een van de familieleden krijgt eens uit het niets een hand toegestoken. Ook de schuurdeuren waaien vanzelf open.","half":"bottom","code":"SINSAG 0478"},"home":"4-3"},{"id":"c5","story_id":"KEMP181","role":"half","render":{"description":"De lichaamsdelen komen samen en vormen zich tot een oude man. Een spook, dat de soldaat steeds bevelen geeft: dat hij naar de kelder moet en een steen optillen etc. De man weigert dit brutaal en laat het spook alles zelf doen. In de hofstee blijken drie potten goud verborgen te zijn. Van de geest moet de soldaat een pot schenken aan de kerk, een aan de armen en een mag hij zelf houden, als dank voor het verlossen van het spook, dat in zijn leven slecht was geweest en armen uitbuitte.","half":"bottom","code":"SINSAG 0401"},"home":"4-3"},{"id":"c6","story_id":"BLECOURTNB0111","role":"half","render":{"description":"Gevraagd naar de reden van de verschijning van de schim, antwoordt deze dat hij haar vader is en pas in de hemel kan komen als er nog drie missen zijn gelezen. Nadat het meisje hieraan heeft voldaan verbetert haar gezondheid.","half":"bottom","code":"SINSAG 0402"},"home":"4-3"},{"id":"c7","story_id":"CJ062011","role":"bottom","render":{"description":"Ze veegt altijd het paadje en het erf met een bezem. Op een avond met volle maan ziet hij het vrouwtje steunend op de bezem weer op het erf staan, hoewel ze al vier maanden dood is.","half":"bottom","code":"SINSAG 0450","stain":"vier"},"home":"4-3"}],"hints":["Lees wat de machine getypt heeft, tot het laatste woord.","Het vervolg noemt ‘vrouw’ opnieuw.","Het nummer is SINSAG 0450. Er zijn er maar drie in de envelop."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c7","object":"typewriter"},"on_success":{"fuse":["c1","c7"],"type_line":"Verteller: de vorige assistent.","digit":{"value":4,"card":"c1","word":"vier","stained":"c7"},"stack":["c1","c2","c3","c4","c5","c6","c7"]}}]},{"id":5,"label":"De duivel","digit":null,"drawers":[]}]});
